  public static func createLFVTestReport(
    _ fbb: inout FlatBufferBuilder,
    TEST_NAMEOffset TEST_NAME: Offset = Offset(),
    STATISTIC_NAMEOffset STATISTIC_NAME: Offset = Offset(),
    STATISTIC: Double = .nan,
    P_VALUE: Double = .nan,
    REAL_COUNT: UInt32 = 0,
    DECOY_COUNT: UInt32 = 0,
    EXCLUDED_FEATURESVectorOffset EXCLUDED_FEATURES: Offset = Offset(),
    RELATIVE: Bool = false,
    CLASSIFIEROffset CLASSIFIER: Offset = Offset(),
    AUC: Double = 0.0,
    BALANCED_ACCURACY: Double = 0.0,
    THRESHOLDSVectorOffset THRESHOLDS: Offset = Offset(),
    RANK_PROBABILITIESVectorOffset RANK_PROBABILITIES: Offset = Offset(),
    CLASS_RESULTSVectorOffset CLASS_RESULTS: Offset = Offset(),
    FEATURESVectorOffset FEATURES: Offset = Offset(),
    WITHIN_GROUPOffset WITHIN_GROUP: Offset = Offset()
  ) -> Offset {
    let __start = LFVTestReport.startLFVTestReport(&fbb)
    LFVTestReport.add(TEST_NAME: TEST_NAME, &fbb)
    LFVTestReport.add(STATISTIC_NAME: STATISTIC_NAME, &fbb)
    LFVTestReport.add(STATISTIC: STATISTIC, &fbb)
    LFVTestReport.add(P_VALUE: P_VALUE, &fbb)
    LFVTestReport.add(REAL_COUNT: REAL_COUNT, &fbb)
    LFVTestReport.add(DECOY_COUNT: DECOY_COUNT, &fbb)
    LFVTestReport.addVectorOf(EXCLUDED_FEATURES: EXCLUDED_FEATURES, &fbb)
    LFVTestReport.add(RELATIVE: RELATIVE, &fbb)
    LFVTestReport.add(CLASSIFIER: CLASSIFIER, &fbb)
    LFVTestReport.add(AUC: AUC, &fbb)
    LFVTestReport.add(BALANCED_ACCURACY: BALANCED_ACCURACY, &fbb)
    LFVTestReport.addVectorOf(THRESHOLDS: THRESHOLDS, &fbb)
    LFVTestReport.addVectorOf(RANK_PROBABILITIES: RANK_PROBABILITIES, &fbb)
    LFVTestReport.addVectorOf(CLASS_RESULTS: CLASS_RESULTS, &fbb)
    LFVTestReport.addVectorOf(FEATURES: FEATURES, &fbb)
    LFVTestReport.add(WITHIN_GROUP: WITHIN_GROUP, &fbb)
    return LFVTestReport.endLFVTestReport(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.TEST_NAME, fieldName: "TEST_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.STATISTIC_NAME, fieldName: "STATISTIC_NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.STATISTIC, fieldName: "STATISTIC", required: false, type: Double.self)
    try _v.visit(field: VT.P_VALUE, fieldName: "P_VALUE", required: false, type: Double.self)
    try _v.visit(field: VT.REAL_COUNT, fieldName: "REAL_COUNT", required: false, type: UInt32.self)
    try _v.visit(field: VT.DECOY_COUNT, fieldName: "DECOY_COUNT", required: false, type: UInt32.self)
    try _v.visit(field: VT.EXCLUDED_FEATURES, fieldName: "EXCLUDED_FEATURES", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.RELATIVE, fieldName: "RELATIVE", required: false, type: Bool.self)
    try _v.visit(field: VT.CLASSIFIER, fieldName: "CLASSIFIER", required: false, type: ForwardOffset<LFVClassifier>.self)
    try _v.visit(field: VT.AUC, fieldName: "AUC", required: false, type: Double.self)
    try _v.visit(field: VT.BALANCED_ACCURACY, fieldName: "BALANCED_ACCURACY", required: false, type: Double.self)
    try _v.visit(field: VT.THRESHOLDS, fieldName: "THRESHOLDS", required: false, type: ForwardOffset<Vector<ForwardOffset<LFVThresholdTest>, LFVThresholdTest>>.self)
    try _v.visit(field: VT.RANK_PROBABILITIES, fieldName: "RANK_PROBABILITIES", required: false, type: ForwardOffset<Vector<ForwardOffset<LFVRankProbability>, LFVRankProbability>>.self)
    try _v.visit(field: VT.CLASS_RESULTS, fieldName: "CLASS_RESULTS", required: false, type: ForwardOffset<Vector<ForwardOffset<LFVClassResult>, LFVClassResult>>.self)
    try _v.visit(field: VT.FEATURES, fieldName: "FEATURES", required: false, type: ForwardOffset<Vector<ForwardOffset<LFVFeatureSeparation>, LFVFeatureSeparation>>.self)
    try _v.visit(field: VT.WITHIN_GROUP, fieldName: "WITHIN_GROUP", required: false, type: ForwardOffset<LFVWithinGroup>.self)
    _v.finish()
  }
}

///  Labelled Feature Vectors - labelled rows and, optionally, the report of a
///  test that distinguishes their classes.
public struct LFV: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$LFV" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: LFV.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let VIEW: VOffset = 4
    static let FEATURE_NAMES: VOffset = 6
    static let FEATURE_UNITS: VOffset = 8
    static let WINDOW_START_MS: VOffset = 10
    static let WINDOW_END_MS: VOffset = 12
    static let MIN_POINTS: VOffset = 14
    static let ROWS: VOffset = 16
    static let SOURCE_COUNT: VOffset = 18
    static let REFERENCE_COUNT: VOffset = 20
    static let SKIPPED_COUNT: VOffset = 22
    static let GENERATED_AT_MS: VOffset = 24
    static let REPORT: VOffset = 26
  }

  ///  Name of the feature set or view, e.g. "gp" (from element sets), "hpop"
  ///  (from propagated ephemeris).
  public var VIEW: String? { let o = _accessor.offset(VT.VIEW); return o == 0 ? nil : _accessor.string(at: o) }
  public var VIEWSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.VIEW) }
  ///  Feature names, in the order of every row's VALUES.
  public var FEATURE_NAMES: FlatbufferVector<String?> { return _accessor.vector(at: VT.FEATURE_NAMES, byteSize: 4) }
  ///  Unit of each feature, same order, e.g. "km", "deg", "km/day", "1";
  ///  empty = not stated.
  public var FEATURE_UNITS: FlatbufferVector<String?> { return _accessor.vector(at: VT.FEATURE_UNITS, byteSize: 4) }
  ///  Window of data the features were computed over, Unix milliseconds
  ///  [start, end); 0 = not stated.
  public var WINDOW_START_MS: Int64 { let o = _accessor.offset(VT.WINDOW_START_MS); return o == 0 ? 0 : _accessor.readBuffer(of: Int64.self, at: o) }
  public var WINDOW_END_MS: Int64 { let o = _accessor.offset(VT.WINDOW_END_MS); return o == 0 ? 0 : _accessor.readBuffer(of: Int64.self, at: o) }
  ///  Fewest data points a source needed to get a row.
  public var MIN_POINTS: UInt32 { let o = _accessor.offset(VT.MIN_POINTS); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  public var ROWS: FlatbufferVector<LFVRow> { return _accessor.vector(at: VT.ROWS, byteSize: 4) }
  ///  Sources offered, reference objects compared against (the catalog),
  ///  and sources skipped for having too few points.
  public var SOURCE_COUNT: UInt32 { let o = _accessor.offset(VT.SOURCE_COUNT); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  public var REFERENCE_COUNT: UInt32 { let o = _accessor.offset(VT.REFERENCE_COUNT); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  public var SKIPPED_COUNT: UInt32 { let o = _accessor.offset(VT.SKIPPED_COUNT); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Unix milliseconds this record was generated; 0 = not stated.
  public var GENERATED_AT_MS: Int64 { let o = _accessor.offset(VT.GENERATED_AT_MS); return o == 0 ? 0 : _accessor.readBuffer(of: Int64.self, at: o) }
  public var REPORT: LFVTestReport? { let o = _accessor.offset(VT.REPORT); return o == 0 ? nil : LFVTestReport(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public static func startLFV(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 12) }
  public static func add(VIEW: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: VIEW, at: VT.VIEW) }
  public static func addVectorOf(FEATURE_NAMES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: FEATURE_NAMES, at: VT.FEATURE_NAMES) }
  public static func addVectorOf(FEATURE_UNITS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: FEATURE_UNITS, at: VT.FEATURE_UNITS) }
  public static func add(WINDOW_START_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: WINDOW_START_MS, def: 0, at: VT.WINDOW_START_MS) }
  public static func add(WINDOW_END_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: WINDOW_END_MS, def: 0, at: VT.WINDOW_END_MS) }
  public static func add(MIN_POINTS: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: MIN_POINTS, def: 0, at: VT.MIN_POINTS) }
  public static func addVectorOf(ROWS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ROWS, at: VT.ROWS) }
  public static func add(SOURCE_COUNT: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: SOURCE_COUNT, def: 0, at: VT.SOURCE_COUNT) }
  public static func add(REFERENCE_COUNT: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: REFERENCE_COUNT, def: 0, at: VT.REFERENCE_COUNT) }
  public static func add(SKIPPED_COUNT: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: SKIPPED_COUNT, def: 0, at: VT.SKIPPED_COUNT) }
  public static func add(GENERATED_AT_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: GENERATED_AT_MS, def: 0, at: VT.GENERATED_AT_MS) }
  public static func add(REPORT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: REPORT, at: VT.REPORT) }
  public static func endLFV(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createLFV(
    _ fbb: inout FlatBufferBuilder,
    VIEWOffset VIEW: Offset = Offset(),
    FEATURE_NAMESVectorOffset FEATURE_NAMES: Offset = Offset(),
    FEATURE_UNITSVectorOffset FEATURE_UNITS: Offset = Offset(),
    WINDOW_START_MS: Int64 = 0,
    WINDOW_END_MS: Int64 = 0,
    MIN_POINTS: UInt32 = 0,
    ROWSVectorOffset ROWS: Offset = Offset(),
    SOURCE_COUNT: UInt32 = 0,
    REFERENCE_COUNT: UInt32 = 0,
    SKIPPED_COUNT: UInt32 = 0,
    GENERATED_AT_MS: Int64 = 0,
    REPORTOffset REPORT: Offset = Offset()
  ) -> Offset {
    let __start = LFV.startLFV(&fbb)
    LFV.add(VIEW: VIEW, &fbb)
    LFV.addVectorOf(FEATURE_NAMES: FEATURE_NAMES, &fbb)
    LFV.addVectorOf(FEATURE_UNITS: FEATURE_UNITS, &fbb)
    LFV.add(WINDOW_START_MS: WINDOW_START_MS, &fbb)
    LFV.add(WINDOW_END_MS: WINDOW_END_MS, &fbb)
    LFV.add(MIN_POINTS: MIN_POINTS, &fbb)
    LFV.addVectorOf(ROWS: ROWS, &fbb)
    LFV.add(SOURCE_COUNT: SOURCE_COUNT, &fbb)
    LFV.add(REFERENCE_COUNT: REFERENCE_COUNT, &fbb)
    LFV.add(SKIPPED_COUNT: SKIPPED_COUNT, &fbb)
    LFV.add(GENERATED_AT_MS: GENERATED_AT_MS, &fbb)
    LFV.add(REPORT: REPORT, &fbb)
    return LFV.endLFV(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.VIEW, fieldName: "VIEW", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FEATURE_NAMES, fieldName: "FEATURE_NAMES", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.FEATURE_UNITS, fieldName: "FEATURE_UNITS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.WINDOW_START_MS, fieldName: "WINDOW_START_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.WINDOW_END_MS, fieldName: "WINDOW_END_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.MIN_POINTS, fieldName: "MIN_POINTS", required: false, type: UInt32.self)
    try _v.visit(field: VT.ROWS, fieldName: "ROWS", required: false, type: ForwardOffset<Vector<ForwardOffset<LFVRow>, LFVRow>>.self)
    try _v.visit(field: VT.SOURCE_COUNT, fieldName: "SOURCE_COUNT", required: false, type: UInt32.self)
    try _v.visit(field: VT.REFERENCE_COUNT, fieldName: "REFERENCE_COUNT", required: false, type: UInt32.self)
    try _v.visit(field: VT.SKIPPED_COUNT, fieldName: "SKIPPED_COUNT", required: false, type: UInt32.self)
    try _v.visit(field: VT.GENERATED_AT_MS, fieldName: "GENERATED_AT_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.REPORT, fieldName: "REPORT", required: false, type: ForwardOffset<LFVTestReport>.self)
    _v.finish()
  }
}
